// ❌ OLD: Dereferencing a raw pointer without verifying it points to a
// valid, aligned, initialized value is undefined behavior. The
// compiler cannot help — this is exactly the class of bug unsafe
// introduces when used carelessly.
fn read(p: *const i32) -> i32 {
    unsafe { *p } // ❌ OLD: if p is null/dangling/misaligned → UB
}

// With a null pointer this crashes (or worse, does something
// unpredictable under optimization). The fix is to VALIDATE before
// dereferencing:
fn read_safe(p: *const i32) -> Option<i32> {
    if p.is_null() {
        None
    } else {
        Some(unsafe { *p }) // still requires the caller to guarantee validity
    }
}

