// ✅ NEW: Safe-style wrapper that upholds the raw-pointer invariants
// (non-null, aligned, pointing at a valid live value) and documents
// the contract — so callers in SAFE code cannot trigger UB.

/// SAFETY: `p` must be non-null, aligned, and point to a valid `i32`
/// that remains alive (and unaliased) for the duration of the call.
fn read_i32(p: *const i32) -> Option<i32> {
    if p.is_null() {
        return None; // ✅ NEW: null check
    }
    if (p as usize) % std::mem::align_of::<i32>() != 0 {
        return None; // ✅ NEW: alignment check
    }
    Some(unsafe { *p }) // ✅ NEW: dereference with invariants met
}

